albums = FileAttachment("data/albums.csv").csv({ typed: true })

viewof selected = Inputs.select(albums, {
  label: "Select an album:",
  format: d =&gt; `${d.artist} - ${d.title} (${d.year})`
})

html`&lt;div style="margin-top: 20px; margin-bottom: 30px;"&gt;
  &lt;img src="data/${selected.cover_filename}" alt="${selected.title}" style="max-width: 400px; width: 100%; border-radius: 8px; box-shadow: 0 4px 6px rgba(0,0,0,0.1);" onerror="this.style.display='none'; this.nextElementSibling.style.display='block';"&gt;
  &lt;p style="display:none; color: #888; font-style: italic;"&gt;Cover image not available.&lt;/p&gt;
&lt;/div&gt;`

Cover Color Similarity

similarity = FileAttachment("data/similarity.csv").csv({ typed: true })

Inputs.table(similarity, {
  columns: ["Artist 1", "Album 1", "Artist 2", "Album 2", "Similarity"],
  format: {
    "Similarity": d =&gt; `${d}%`
  },
  rows: 15,
  sort: "Similarity",
  reverse: true
})
